import React, { useState } from 'react';
import { Calendar, Clock, History, Truck, CheckCircle2, AlertCircle, ChevronRight, ChevronLeft, Filter } from 'lucide-react';

const CollectionSchedule = () => {
  const [timeFrame, setTimeFrame] = useState('CURRENT'); // CURRENT, WEEKLY, MONTHLY
  const [selectedLog, setSelectedLog] = useState(null);

  const scheduleData = [
    { id: 'JOB-101', route: 'Sector_Alpha_Loop', worker: 'Ravi_K', status: 'IN_PROGRESS', progress: 65, eta: '14:30', quality: 'High' },
    { id: 'JOB-102', route: 'North_Ridge_Path', worker: 'Sita_M', status: 'COMPLETED', progress: 100, eta: 'DONE', quality: 'Optimal' },
    { id: 'JOB-103', route: 'Central_Hub_Express', worker: 'John_D', status: 'PENDING', progress: 0, eta: '16:00', quality: 'N/A' },
  ];

  return (
    <div className="w-full h-full flex flex-col gap-8 animate-slot">

      {/* 🛠️ TOP CONTROL BLOCK: TRIPLE TOGGLE */}
      <div className="relative group">
        <div className="absolute inset-0 bg-[#47510B] translate-x-2 translate-y-2 rounded-[40px]" />
        <div className="relative bg-[#A1AED1] border-[6px] border-[#47510B] p-6 rounded-[40px] flex flex-col md:flex-row justify-between items-center gap-6">
          <div className="flex gap-3 bg-[#47510B]/20 p-2 rounded-full border-[3px] border-[#47510B]">
            {['CURRENT', 'WEEKLY', 'MONTHLY'].map((mode) => (
              <button
                key={mode}
                onClick={() => setTimeFrame(mode)}
                className={`px-6 py-2 rounded-full font-[1000] italic text-xs transition-all uppercase ${
                  timeFrame === mode 
                  ? 'bg-[#FF5B03] text-white shadow-[4px_4px_0_0_#47510B]' 
                  : 'text-[#47510B] hover:bg-white/30'
                }`}
              >
                {mode}
              </button>
            ))}
          </div>

          <div className="flex items-center gap-4">
             <div className="bg-[#FDFAD8] border-[4px] border-[#47510B] px-6 py-2 rounded-full font-black italic text-[#47510B] flex items-center gap-2">
                <Calendar size={18} />
                MARCH_2026
             </div>
             <button className="bg-[#CAD23C] border-[4px] border-[#47510B] p-2 rounded-full hover:rotate-90 transition-transform shadow-[3px_3px_0_0_#47510B]">
                <Filter size={20} />
             </button>
          </div>
        </div>
      </div>

      {/* 🌊 DYNAMIC CONTENT VIEW */}
      <div className="flex-grow overflow-y-auto pr-2 custom-scrollbar">

        {/* --- VIEW 01: CURRENT (Live Feed) --- */}
        {timeFrame === 'CURRENT' && (
          <div className="flex flex-col gap-8 pb-10">
            {scheduleData.map((job) => (
              <div key={job.id} className="relative group cursor-crosshair">
                <div className="absolute inset-0 bg-[#47510B] translate-x-2 translate-y-2 rounded-[45px]" />
                <div className="relative bg-white border-[6px] border-[#47510B] p-8 rounded-[45px] flex flex-col md:flex-row items-center gap-10 group-hover:bg-[#FDFAD8] transition-all">

                  {/* Vehicle Identity */}
                  <div className="flex flex-col items-center gap-2">
                    <div className="w-24 h-24 bg-[#CAD23C] border-[5px] border-[#47510B] rounded-[30px] flex items-center justify-center text-[#47510B] shadow-[6px_6px_0_0_#47510B]">
                      <Truck size={40} />
                    </div>
                    <span className="font-black text-[10px] bg-[#AB1717] text-white px-3 py-1 rounded-md uppercase tracking-tighter shadow-[2px_2px_0_0_#47510B]">
                      {job.id}
                    </span>
                  </div>

                  {/* Route Info */}
                  <div className="flex-grow text-center md:text-left">
                    <h3 className="text-4xl font-[1000] italic text-[#47510B] uppercase leading-none mb-2 tracking-tighter">
                      {job.route}
                    </h3>
                    <div className="flex flex-wrap justify-center md:justify-start gap-4">
                      <div className="flex items-center gap-2 text-xs font-black text-[#AB1717]">
                        <Clock size={14} /> ETA: {job.eta}
                      </div>
                      <div className="flex items-center gap-2 text-xs font-black text-[#47510B]/40">
                        OP: {job.worker}
                      </div>
                    </div>
                  </div>

                  {/* Progress Matrix */}
                  <div className="w-full md:w-64 flex flex-col gap-2">
                    <div className="flex justify-between text-[10px] font-black uppercase text-[#47510B]">
                      <span>Completion</span>
                      <span>{job.progress}%</span>
                    </div>
                    <div className="h-6 w-full bg-[#47510B] rounded-full border-[3px] border-[#47510B] overflow-hidden p-1 shadow-inner">
                      <div 
                        className="h-full bg-[#FF5B03] rounded-full transition-all duration-1000" 
                        style={{ width: `${job.progress}%` }} 
                      />
                    </div>
                  </div>

                  {/* Status Sticker */}
                  <div className="bg-[#47510B] text-[#CAD23C] px-8 py-3 rounded-[25px] font-[1000] italic uppercase shadow-[6px_6px_0_0_#AB1717]">
                    {job.status}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* --- VIEW 02: WEEKLY (The Grid Log) --- */}
        {timeFrame === 'WEEKLY' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-7 gap-6 py-4">
            {['MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT', 'SUN'].map((day, i) => (
              <div key={day} className="relative group">
                <div className="absolute inset-0 bg-[#47510B] translate-x-1.5 translate-y-1.5 rounded-[30px]" />
                <div className={`relative h-64 border-[5px] border-[#47510B] rounded-[30px] p-4 flex flex-col items-center justify-between transition-all ${i < 3 ? 'bg-[#CAD23C]' : 'bg-white'}`}>
                  <span className="text-2xl font-[1000] italic text-[#47510B]">{day}</span>
                  <div className="flex flex-col items-center gap-1">
                    <div className="w-12 h-12 bg-white/50 border-[3px] border-[#47510B] rounded-xl flex items-center justify-center">
                      {i < 3 ? <CheckCircle2 className="text-[#47510B]" /> : <Clock className="text-[#AB1717] opacity-30" />}
                    </div>
                    <span className="text-[10px] font-black uppercase tracking-tighter">{i < 3 ? 'DONE' : 'PENDING'}</span>
                  </div>
                  <div className="text-[9px] font-black bg-[#47510B] text-white px-3 py-1 rounded-full italic">
                    12_BINS
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* --- VIEW 03: MONTHLY (Density Matrix) --- */}
        {timeFrame === 'MONTHLY' && (
          <div className="bg-[#47510B] border-[8px] border-[#47510B] rounded-[45px] p-8 shadow-[12px_12px_0_0_#AB1717] overflow-hidden">
             <div className="grid grid-cols-7 gap-4">
                {[...Array(31)].map((_, i) => (
                  <div 
                    key={i} 
                    className={`aspect-square rounded-[15px] border-[4px] border-[#47510B] flex items-center justify-center font-black italic transition-all cursor-pointer hover:scale-110 ${
                      i % 7 === 0 ? 'bg-[#AB1717] text-white rotate-2' : 
                      i % 3 === 0 ? 'bg-[#CAD23C] text-[#47510B]' : 'bg-[#FDFAD8] text-[#47510B]'
                    }`}
                  >
                    {i + 1}
                  </div>
                ))}
             </div>
             <div className="mt-8 flex justify-center gap-8">
                <div className="flex items-center gap-2 text-[#CAD23C] font-black italic text-xs uppercase tracking-widest"><div className="w-4 h-4 bg-[#CAD23C] rounded-sm" /> Optimal_Performance</div>
                <div className="flex items-center gap-2 text-[#AB1717] font-black italic text-xs uppercase tracking-widest"><div className="w-4 h-4 bg-[#AB1717] rounded-sm" /> System_Failure</div>
             </div>
          </div>
        )}

      </div>

      {/* 🧭 FOOTER SUMMARY */}
      <div className="mt-auto flex justify-between items-center p-6 bg-[#47510B] rounded-[35px] border-[4px] border-white shadow-[8px_8px_0_0_#CAD23C]">
        <div className="flex gap-10">
          <div>
            <p className="text-[10px] font-black text-[#A1AED1] uppercase tracking-widest">Total_Jobs</p>
            <p className="text-2xl font-[1000] italic text-white uppercase leading-none">1,422_Logs</p>
          </div>
          <div>
            <p className="text-[10px] font-black text-[#A1AED1] uppercase tracking-widest">Completion_Rate</p>
            <p className="text-2xl font-[1000] italic text-[#CAD23C] uppercase leading-none">98.4%_Success</p>
          </div>
        </div>
        <button className="bg-[#FF5B03] text-white px-10 py-3 rounded-full font-[1000] italic uppercase border-[4px] border-[#47510B] hover:-translate-y-1 transition-transform">
          Download_Report.csv
        </button>
      </div>

    </div>
  );
};

export default CollectionSchedule;
